#include <stdio.h>
#define MAX 5

int stack[MAX];
int top = -1;

void push(int val) {
    if (top == MAX - 1) {
        printf("Stack Overflow! Cannot push %d\n", val);
        return;
    }
    stack[++top] = val;
    printf("Pushed %d (top = %d)\n", val, top);
}

int pop(void) {
    if (top == -1) {
        printf("Stack Underflow! Stack is empty\n");
        return -1;
    }
    return stack[top--];
}

int peek(void) {
    if (top == -1) return -1;
    return stack[top];
}

void display(void) {
    if (top == -1) {
        printf("Stack is empty\n");
        return;
    }
    printf("Stack (top to bottom): ");
    for (int i = top; i >= 0; i--) printf("%d ", stack[i]);
    printf("\n");
}

int main(void) {
    push(10);
    push(20);
    push(30);
    display();
    printf("Top element: %d\n", peek());
    printf("Popped: %d\n", pop());
    display();
    return 0;
}

infix_to_postfix.c_program:
#include <stdio.h>
#include <ctype.h>
#include <string.h>

char stack[100];
int top = -1;

void push(char c) { stack[++top] = c; }
char pop() { return (top == -1) ? -1 : stack[top--]; }
char peek() { return (top == -1) ? -1 : stack[top]; }

int precedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}

void infixToPostfix(char infix[], char postfix[]) {
    int k = 0;
    for (int i = 0; infix[i] != '\0'; i++) {
        char ch = infix[i];
        if (isalnum(ch)) {
            postfix[k++] = ch;
        } else if (ch == '(') {
            push(ch);
        } else if (ch == ')') {
            while (top != -1 && peek() != '(') {
                postfix[k++] = pop();
            }
            pop(); // Remove '('
        } else {
            while (top != -1 && precedence(peek()) >= precedence(ch)) {
                postfix[k++] = pop();
            }
            push(ch);
        }
    }
    while (top != -1) postfix[k++] = pop();
    postfix[k] = '\0';
}

int main(void) {
    char infix[] = "(A+B)*C-D/E";
    char postfix[100];
    infixToPostfix(infix, postfix);
    printf("Infix:   %s\n", infix);
    printf("Postfix: %s\n", postfix);
    return 0;
}

parentheses_matching.c_program:
#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool isMatchingPair(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '{' && close == '}') ||
           (open == '[' && close == ']');
}

bool checkBalanced(char exp[]) {
    char stack[100];
    int top = -1;

    for (int i = 0; exp[i] != '\0'; i++) {
        char ch = exp[i];
        if (ch == '(' || ch == '{' || ch == '[') {
            stack[++top] = ch;
        } else if (ch == ')' || ch == '}' || ch == ']') {
            if (top == -1) return false; // Closing without opening
            char open = stack[top--];
            if (!isMatchingPair(open, ch)) return false; // Mismatched type
        }
    }
    return top == -1; // True if stack completely empty
}

int main(void) {
    char exp1[] = "{[()]}";
    char exp2[] = "{[(])}";
    printf("%s is %s\n", exp1, checkBalanced(exp1) ? "BALANCED" : "NOT BALANCED");
    printf("%s is %s\n", exp2, checkBalanced(exp2) ? "BALANCED" : "NOT BALANCED");
    return 0;
}
